// @generated by:gauntlet run:godseye-local-delivery
import { randomUUID } from "node:crypto";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { prepareDelivery } from "../packages/core/src/delivery-preparation.js";
import { type DeliveryFixture, deliveryFixture } from "./delivery-helpers.js";

describe("immutable delivery preparation from independently verified source", () => {
  let fixture: DeliveryFixture;
  beforeEach(async () => {
    fixture = await deliveryFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });
  it("T-AC-44 T-AC-46 freezes the current accepted source without starting a build or claiming readiness", async () => {
    const policy = await fixture.createPolicy(),
      ci = await fixture.push();
    const preparation = await fixture.prepare({
      policyId: policy.id,
      ciRunId: ci.id,
      intent: "build",
    });
    expect(preparation).toMatchObject({
      policyId: policy.id,
      projectId: fixture.project.id,
      environmentId: fixture.development.id,
      ciRunId: ci.id,
      intent: "build",
      commitSha: fixture.source.head,
    });
    expect(fixture.source.requests).toHaveLength(1);
    expect(fixture.provider.effects).toEqual([]);
    expect(await fixture.store.db.select().from(schema.deliveryArtifacts)).toEqual([]);
  });
  it("T-AC-44 T-AC-45 replays one immutable preparation and rejects changed intent under its key", async () => {
    const policy = await fixture.createPolicy(),
      ci = await fixture.push(),
      input = { policyId: policy.id, ciRunId: ci.id, intent: "build" as const },
      key = randomUUID();
    const first = await fixture.prepare(input, key);
    expect(await fixture.prepare(input, key)).toEqual(first);
    await expect(fixture.prepare({ ...input, intent: "release" }, key)).rejects.toMatchObject({
      code: "IDEMPOTENCY_CONFLICT",
    });
    expect(await fixture.store.db.select().from(schema.deliveryPreparations)).toHaveLength(1);
  });
  it.each([
    "head",
    "installation",
    "repository",
    "name",
    "ref",
    "inactive",
    "fork",
    "stale",
    "future",
    "truthy-origin",
  ])("T-AC-44 denies %s source proof before creating execution authority", async (mode) => {
    const policy = await fixture.createPolicy(),
      ci = await fixture.push();
    fixture.source.result = (proof) => {
      if (mode === "head") proof.commitSha = "b".repeat(40);
      if (mode === "installation") proof.installationId += 1;
      if (mode === "repository") proof.repositoryId += 1;
      if (mode === "name") proof.fullName = "other/source";
      if (mode === "ref") proof.branch = "other";
      if (mode === "inactive") proof.installationActive = false;
      if (mode === "fork") proof.sameRepository = false;
      if (mode === "stale") proof.observedAt = "2026-11-11T11:59:29.000Z";
      if (mode === "future") proof.observedAt = "2026-11-11T12:00:01.000Z";
      if (mode === "truthy-origin") Object.assign(proof, { sameRepository: "true" });
      return proof;
    };
    await expect(
      fixture.prepare({ policyId: policy.id, ciRunId: ci.id, intent: "build" }),
    ).rejects.toBeDefined();
    expect(await fixture.store.db.select().from(schema.deliveryPreparations)).toEqual([]);
    expect(fixture.provider.effects).toEqual([]);
  });
  it("T-AC-44 never uses a historic signed event to replace a newer live branch head", async () => {
    const policy = await fixture.createPolicy(),
      current = await fixture.push("b".repeat(40)),
      old = await fixture.push("a".repeat(40));
    fixture.source.head = current.commitSha;
    await expect(
      fixture.prepare({ policyId: policy.id, ciRunId: old.id, intent: "build" }),
    ).rejects.toMatchObject({ code: "STALE_HEAD" });
    expect(
      (await fixture.prepare({ policyId: policy.id, ciRunId: current.id, intent: "build" }))
        .commitSha,
    ).toBe(current.commitSha);
  });
  it("T-AC-47 rechecks policy revocation after awaited source verification before persisting a preparation", async () => {
    const policy = await fixture.createPolicy(),
      ci = await fixture.push();
    fixture.source.beforeResolve = async () => {
      await fixture.store.db
        .update(schema.deliveryPolicies)
        .set({ revokedAt: fixture.clock.now() })
        .where(eq(schema.deliveryPolicies.id, policy.id));
    };
    await expect(
      fixture.prepare({ policyId: policy.id, ciRunId: ci.id, intent: "build" }),
    ).rejects.toMatchObject({ code: "POLICY_REVOKED" });
    expect(await fixture.store.db.select().from(schema.deliveryPreparations)).toEqual([]);
  });
  it("T-AC-45 denies private delegated authority requested by a caller that happens to share the scheduler name", async () => {
    const policy = await fixture.createPolicy(),
      ci = await fixture.push();
    await expect(
      prepareDelivery(
        fixture.state,
        { id: "delivery-scheduler", kind: "owner", projectIds: [fixture.project.id] },
        { policyId: policy.id, ciRunId: ci.id, intent: "build" },
        randomUUID(),
        true,
      ),
    ).rejects.toMatchObject({ code: "FORBIDDEN" });
  });
  it("T-AC-49 creates one new synthetic preview cell from a verified open same-origin PR and retains production metadata", async () => {
    const policy = await fixture.createPolicy(),
      ci = await fixture.pull(),
      before = await fixture.core.getProject(fixture.freshOwner(), fixture.project.id);
    const preparation = await fixture.prepare({
      policyId: policy.id,
      ciRunId: ci.id,
      intent: "build",
    });
    const project = await fixture.core.getProject(fixture.freshOwner(), fixture.project.id),
      preview = project.environments.find((env) => env.id === preparation.environmentId);
    expect(preview).toMatchObject({
      kind: "preview",
      recoveryHold: false,
      expiresAt: new Date(fixture.clock.now().getTime() + 24 * 3_600_000).toISOString(),
    });
    expect(preparation.environmentId).not.toBe(fixture.development.id);
    expect(project.environments.filter((env) => env.kind !== "preview")).toEqual(
      before.environments,
    );
    expect(await fixture.store.db.select().from(schema.databaseAllocations)).toEqual([]);
    expect(await fixture.store.db.select().from(schema.serviceIdentities)).toEqual([]);
    expect((await fixture.store.db.select().from(schema.deliveryPreviews))[0]).toMatchObject({
      state: "prepared",
      url: null,
    });
  });
  it("T-AC-49 counts retained preview cells and rejects capacity beyond a policy's finite preview limit", async () => {
    const policy = await fixture.createPolicy({ maxConcurrentPreviews: 1 }),
      first = await fixture.pull(1),
      second = await fixture.pull(2);
    await fixture.prepare({ policyId: policy.id, ciRunId: first.id, intent: "build" });
    await expect(
      fixture.prepare({ policyId: policy.id, ciRunId: second.id, intent: "build" }),
    ).rejects.toMatchObject({ code: "PREVIEW_LIMIT" });
    expect(await fixture.store.db.select().from(schema.deliveryPreviews)).toHaveLength(1);
  });
  it("T-AC-44 T-AC-49 refuses a stale close event when GitHub currently reports the PR reopened", async () => {
    const policy = await fixture.createPolicy(),
      opened = await fixture.pull(),
      closed = await fixture.pull(42, "closed");
    await fixture.prepare({ policyId: policy.id, ciRunId: opened.id, intent: "build" });
    fixture.source.open = true;
    await expect(
      fixture.prepare({ policyId: policy.id, ciRunId: closed.id, intent: "cleanup" }),
    ).rejects.toMatchObject({ code: "PREVIEW_OPEN" });
    expect((await fixture.store.db.select().from(schema.deliveryPreviews))[0]?.state).toBe(
      "prepared",
    );
  });
});
